// SQL as text for witness: pure string work, no DOM, no Node, no imports.
// Aware of single-quoted strings, double-quoted identifiers, dollar-quoted bodies
// and comments. Analysis runs on a same-length "masked" copy of the SQL in which
// comments, string contents and dollar bodies are blank and quoted identifiers
// are lower-cased with their quotes blanked.

export interface BareWrite {
  readonly verb: 'UPDATE' | 'DELETE'
  readonly table: string
  readonly statement: string
}

interface Stmt {
  readonly original: string
  readonly masked: string
}

interface Found {
  readonly verb: 'UPDATE' | 'DELETE'
  readonly table: string
  readonly from: number
  readonly to: number
  readonly top: boolean
  readonly atStart: boolean
}

const NAME = '[\\w$]+(?:\\s*\\.\\s*[\\w$]+)*'
const UPDATE_RE = new RegExp(`\\bupdate\\s+(?:only\\s+)?(${NAME})(?:\\s+(?:as\\s+)?[\\w$]+)?\\s+set\\b`, 'gi')
const DELETE_RE = new RegExp(`\\bdelete\\s+from\\s+(?:only\\s+)?(${NAME})`, 'gi')
const INSERT_RE = new RegExp(`\\binsert\\s+into\\s+(${NAME})`, 'gi')
const MERGE_RE = new RegExp(`\\bmerge\\s+into\\s+(?:only\\s+)?(${NAME})`, 'gi')
const TRUNCATE_RE = /\btruncate\s+(?:table\s+)?(?:only\s+)?/gi
// The estate's list, as config.ts DEFAULT_WRITERS builds it; the default when none is passed.
const WRITER_RE =
  /\b(workspace\s*\.\s*(?:close_todo|set_todo_status|pause_todo|crosstalk_[a-z_]+|record_board_attention|claim_item|release_claim))\s*\(/gi
const FUNCTION_FORMS = new Set(['extract', 'substring', 'trim', 'overlay', 'position'])
const KEYWORDS = new Set([
  'where', 'join', 'left', 'right', 'inner', 'outer', 'full', 'cross', 'natural', 'on', 'using',
  'group', 'order', 'limit', 'union', 'returning', 'set', 'having', 'window', 'for', 'offset',
  'fetch', 'except', 'intersect', 'lateral', 'tablesample', 'with', 'restart', 'cascade',
  'restrict', 'continue', 'when', 'values', 'select',
])

function skipLine(sql: string, i: number): number {
  let j = i
  while (j < sql.length && sql[j] !== '\n') j++
  return j
}

function blank(len: number): string {
  return ' '.repeat(len)
}

/** An E'...' string: a backslash escapes the next character, `\'` included. */
function isEscapeString(sql: string, i: number): boolean {
  const prev = sql[i - 1] ?? ''
  const before = sql[i - 2] ?? ' '
  return (prev === 'E' || prev === 'e') && !/[A-Za-z0-9_$]/.test(before)
}

function maskQuoted(sql: string, i: number, q: string): { out: string; end: number } {
  const escapes = q === "'" && isEscapeString(sql, i)
  let j = i + 1
  while (j < sql.length) {
    if (escapes && sql[j] === '\\') {
      j += 2
      continue
    }
    if (sql[j] === q) {
      if (sql[j + 1] === q) {
        j += 2
        continue
      }
      break
    }
    j++
  }
  const end = Math.min(j + 1, sql.length)
  const inner = sql.slice(i + 1, Math.min(j, sql.length))
  if (q === "'") return { out: `'${blank(inner.length)}${j < sql.length ? "'" : ''}`, end }
  const ident = inner.toLowerCase().replace(/[\s"]/g, '_')
  return { out: ` ${ident}${j < sql.length ? ' ' : ''}`, end }
}

export function maskSql(sql: string): string {
  let out = ''
  let i = 0
  while (i < sql.length) {
    const c = sql[i] ?? ''
    const nx = sql[i + 1]
    if (c === '-' && nx === '-') {
      const e = skipLine(sql, i)
      out += blank(e - i)
      i = e
    } else if (c === '/' && nx === '*') {
      const k = sql.indexOf('*/', i + 2)
      const e = k === -1 ? sql.length : k + 2
      out += sql.slice(i, e).replace(/[^\n]/g, ' ')
      i = e
    } else if (c === "'" || c === '"') {
      const r = maskQuoted(sql, i, c)
      out += r.out
      i = r.end
    } else if (c === '$' && /^\$([A-Za-z_][A-Za-z0-9_]*)?\$/.test(sql.slice(i))) {
      const tag = (/^\$([A-Za-z_][A-Za-z0-9_]*)?\$/.exec(sql.slice(i)) as RegExpExecArray)[0]
      const k = sql.indexOf(tag, i + tag.length)
      const e = k === -1 ? sql.length : k + tag.length
      out += sql.slice(i, e).replace(/[^\n]/g, ' ')
      i = e
    } else {
      out += c
      i++
    }
  }
  return out
}

function splitStmts(sql: string): Stmt[] {
  const masked = maskSql(sql)
  const result: Stmt[] = []
  let start = 0
  for (let i = 0; i <= masked.length; i++) {
    if (i === masked.length || masked[i] === ';') {
      const m = masked.slice(start, i)
      if (m.trim() !== '') result.push({ original: sql.slice(start, i), masked: m })
      start = i + 1
    }
  }
  return result
}

export function statements(sql: string): string[] {
  return splitStmts(sql).map((s) => s.original.trim())
}

function normName(raw: string): string {
  return raw.replace(/\s+/g, '').toLowerCase()
}

function depthsOf(masked: string): number[] {
  const d: number[] = []
  let cur = 0
  for (const c of masked) {
    d.push(cur)
    if (c === '(') cur++
    else if (c === ')') cur--
  }
  d.push(cur)
  return d
}

function prevContentChar(masked: string, at: number): string {
  for (let i = at - 1; i >= 0; i--) {
    const c = masked[i] ?? ''
    if (!/\s/.test(c)) return c
  }
  return ''
}

function bodyEnd(masked: string, depths: readonly number[], from: number): number {
  for (let i = from; i < masked.length; i++) {
    if (masked[i] === ')' && depths[i] === depths[from]) return i
  }
  return masked.length
}

function findWrites(stmt: Stmt): Found[] {
  const { masked } = stmt
  const depths = depthsOf(masked)
  const first = masked.search(/\S/)
  const found: Found[] = []
  const scan = (re: RegExp, verb: 'UPDATE' | 'DELETE') => {
    for (const m of masked.matchAll(re)) {
      const from = m.index ?? 0
      const prev = prevContentChar(masked, from)
      const top = prev === '' || (prev === ')' && depths[from] === 0)
      if (!(top || prev === '(')) continue
      if (verb === 'UPDATE' && normName(m[1] ?? '') === 'set') continue
      const to = top ? masked.length : bodyEnd(masked, depths, from)
      found.push({ verb, table: normName(m[1] ?? ''), from, to, top, atStart: from === first })
    }
  }
  scan(UPDATE_RE, 'UPDATE')
  scan(DELETE_RE, 'DELETE')
  return found.sort((a, b) => a.from - b.from)
}

function hasReturning(masked: string, f: Found): boolean {
  return /\breturning\b/i.test(masked.slice(f.from, f.to))
}

function bareIn(stmt: Stmt): BareWrite[] {
  return findWrites(stmt)
    .filter((f) => !hasReturning(stmt.masked, f))
    .map((f) => ({
      verb: f.verb,
      table: f.table,
      statement: stmt.original.slice(f.from, f.to).trim(),
    }))
}

export function bareWrites(sql: string): BareWrite[] {
  return splitStmts(sql).flatMap(bareIn)
}

export function needsHold(sql: string): boolean {
  return bareWrites(sql).length > 0
}

/**
 * The CTE form of a single bare top-level UPDATE or DELETE, or null whenever the
 * rewrite cannot be proved to carry the whole statement: an unclosed string,
 * identifier, comment or dollar body (the mask then no longer lines up with the
 * text), or a body that is not the statement minus trailing blanks. A null offers
 * only "let through" and "cancel": never guess at a cut that could drop a WHERE.
 */
export function withReturning(sql: string): string | null {
  if (maskSql(sql).length !== sql.length) return null
  const stmts = splitStmts(sql)
  if (stmts.length !== 1) return null
  const stmt = stmts[0] as Stmt
  if (stmt.masked.length !== stmt.original.length) return null
  const writes = findWrites(stmt)
  const w = writes[0]
  if (writes.length !== 1 || !w || !w.atStart || !w.top || hasReturning(stmt.masked, w)) return null
  const end = stmt.masked.trimEnd().length
  const body = stmt.original.slice(w.from, end)
  const whole = stmt.original.slice(0, end).trim()
  if (body.trim() !== whole || !/\bwhere\b/i.test(stmt.masked)) return null
  return `WITH w AS (${body} RETURNING *) SELECT * FROM w`
}

function ctesIn(masked: string): Set<string> {
  const names = new Set<string>()
  for (const m of masked.matchAll(/([\w$]+)\s+as\s+(?:not\s+)?(?:materialized\s+)?\(/gi)) {
    names.add((m[1] ?? '').toLowerCase())
  }
  return names
}

function parseList(masked: string, start: number, commas: boolean): string[] {
  const names: string[] = []
  let pos = start
  const nameRe = new RegExp(`(?:only\\s+)?(?:lateral\\s+)?(${NAME})`, 'iy')
  const aliasRe = /\s*(?:as\s+)?([\w$]+)/iy
  for (;;) {
    nameRe.lastIndex = pos
    const m = nameRe.exec(masked)
    if (!m) break
    pos = nameRe.lastIndex
    if (/^\s*\(/.test(masked.slice(pos))) break
    names.push(normName(m[1] ?? ''))
    aliasRe.lastIndex = pos
    const a = aliasRe.exec(masked)
    if (a && !KEYWORDS.has((a[1] ?? '').toLowerCase())) pos = aliasRe.lastIndex
    const rest = /^\s*,\s*/.exec(masked.slice(pos))
    if (!commas || !rest) break
    pos += rest[0].length
  }
  return names
}

function inFunctionForm(masked: string, at: number): boolean {
  let depth = 0
  for (let i = at - 1; i >= 0; i--) {
    const c = masked[i]
    if (c === ')') depth++
    else if (c === '(') {
      if (depth === 0) {
        const w = /([\w$]+)\s*$/.exec(masked.slice(0, i))
        return !!w && FUNCTION_FORMS.has((w[1] ?? '').toLowerCase())
      }
      depth--
    }
  }
  return false
}

function listsAfter(masked: string, re: RegExp, commas: boolean): string[] {
  return [...masked.matchAll(re)].flatMap((m) =>
    parseList(masked, (m.index ?? 0) + m[0].length, commas),
  )
}

function readsIn(masked: string): string[] {
  const ctes = ctesIn(masked)
  const out: string[] = []
  for (const m of masked.matchAll(/\b(from|join)\s+/gi)) {
    const at = m.index ?? 0
    const before = masked.slice(0, at)
    if (/\bdelete\s+$/i.test(before) || /\bdistinct\s+$/i.test(before)) continue
    if (inFunctionForm(masked, at)) continue
    out.push(...parseList(masked, at + m[0].length, (m[1] ?? '').toLowerCase() === 'from'))
  }
  if (/\b(delete\s+from|merge\s+into)\b/i.test(masked)) {
    out.push(...listsAfter(masked, /\busing\s+/gi, true))
  }
  return out.filter((n) => !ctes.has(n))
}

function writesIn(masked: string): string[] {
  const out: string[] = []
  for (const re of [UPDATE_RE, DELETE_RE, INSERT_RE, MERGE_RE]) {
    for (const m of masked.matchAll(re)) {
      const n = normName(m[1] ?? '')
      if (n !== 'set') out.push(n)
    }
  }
  out.push(...listsAfter(masked, TRUNCATE_RE, true))
  return out
}

function unique(items: readonly string[]): string[] {
  return [...new Set(items)]
}

export function tablesWritten(sql: string): string[] {
  return unique(splitStmts(sql).flatMap((s) => writesIn(s.masked)))
}

export function tablesRead(sql: string): string[] {
  return unique(splitStmts(sql).flatMap((s) => readsIn(s.masked)))
}

/** Writer calls in a SELECT; `writers` is the configured pattern (default: the estate's list). */
export function writerCalls(sql: string, writers: RegExp | null = WRITER_RE): string[] {
  if (writers === null) return []
  const calls: string[] = []
  for (const s of splitStmts(sql)) {
    for (const m of s.masked.matchAll(writers)) {
      if (/\bselect\b/i.test(s.masked.slice(0, m.index ?? 0))) calls.push(normName(m[1] ?? ''))
    }
  }
  return unique(calls)
}

files.hooks/support.ts:
// Pure helpers for register.tsx. The engine follows `$` only into functions of the
// hooks module's own file, so everything that calls `$` lives there; what can be
// decided from plain data lives here, where tests reach it.

import type { Ask, Ledger, LogBinding, LogTouchKind } from '../types'
import { PRINT_END, cleanText, counts } from './asks'
import {
  DEFAULT_CLOSE_COMMANDS,
  DEFAULT_PERSON,
  DEFAULT_SESSIONS_DIR,
  ESTATE_TACKLE_SKILL,
  isCloseCommand as isConfiguredClose,
  personRef,
  under,
} from './config'
import { CONFIRM_TOOL } from './evidence'
import { normPath, paleCount } from './witness'

export const HELPER_TIMEOUT_MS = 45_000
export const SIDE_PASS = { model: 'haiku', effort: 'low', timeoutMs: 20_000 } as const
export const PRINT_HEADING = '## Witness print'

let seq = 0

/** Ids unique within the session: time, a counter, and a little noise. */
export function newIds(now: number, n: number, prefix: string): string[] {
  return Array.from({ length: n }, () => {
    seq += 1
    const noise = Math.random().toString(36).slice(2, 6)
    return `${prefix}${now.toString(36)}${seq.toString(36)}${noise}`
  })
}

/** The store key for a project: its folder, lower-case, forward slashes. */
export function projectKey(cwd: string): string {
  return cwd.replace(/\\/g, '/').replace(/\/+$/, '').toLowerCase()
}

export function storeKeys(key: string): {
  carry: string
  friction: string
  barnacles: string
  candidates: string
  scrubbed: string
} {
  return {
    carry: `carry:${key}`,
    friction: `friction:${key}`,
    barnacles: `barnacles:${key}`,
    candidates: `candidates:${key}`,
    // When each barnacle key was last scrubbed off the shell (/barnacles, 1.1): epoch ms by key.
    scrubbed: `scrubbed:${key}`,
  }
}

/** The session-log folder: config `sessionsDir` under the session's folder (default .claude/sessions). */
export function sessionsDir(cwd: string, dir: string = DEFAULT_SESSIONS_DIR): string {
  return under(cwd, dir)
}

/** Text that may reach the session log or a prompt: one line, whitespace collapsed. */
export function askText(text: string): string {
  return cleanText(text)
}

// ---- the session log this watch follows (1.1) ----
//
// Until 1.1 the log was found by listing the sessions folder: every log touched since the
// session started, newest name first, the first one not closed. Two sessions in one repo
// then converged on the newest open log (seen 2026-10-09: a side session took the main
// session's Goals as its own asks and wrote its print into the main session's log). Now
// the watch binds to a log only by the main loop's own file calls.

/** One session-log touch: the log's path as the fs takes it, and what touched it. */
export type LogTouch = { path: string; by: LogTouchKind }

const LOG_TOOLS: ReadonlyMap<string, LogTouchKind> = new Map([
  ['Write', 'write'],
  ['Edit', 'edit'],
  ['Read', 'read'],
])
const LOG_RANK: Readonly<Record<LogTouchKind, number>> = { read: 1, edit: 2, write: 3 }

/**
 * A file call's path as the fs takes it: forward slashes, `.` and `..` resolved, relative
 * under the session's folder, and on Windows Git Bash's `/c/x` as `C:/x`.
 */
export function logPath(raw: string, cwd: string): string {
  const slashed = raw.trim().replace(/\\/g, '/')
  const windows = /^[A-Za-z]:/.test(cwd.trim())
  const drive = windows ? slashed.replace(/^\/([A-Za-z])(?=\/|$)/, (_m: string, d: string) => `${d.toUpperCase()}:`) : slashed
  return under(cwd, drive)
}

/** Two paths name one file: case, slashes and Git Bash's `/c/` aside (normPath). */
export function sameFile(a: string, b: string): boolean {
  return normPath(a) === normPath(b)
}

/**
 * The session log a main-loop file call touched: a `.md` file directly under the sessions
 * folder, by a Write (it created the log), an Edit or a Read (it opened one). Any other
 * tool, a nested folder, another folder or another kind of file is null. The caller passes
 * only the main loop's own calls that did not fail: a subagent's call binds nothing.
 */
export function logTouch(
  tool: string,
  input: Readonly<Record<string, unknown>>,
  cwd: string,
  dir: string = DEFAULT_SESSIONS_DIR,
): LogTouch | null {
  const by = LOG_TOOLS.get(tool)
  const raw = input.file_path
  if (by === undefined || typeof raw !== 'string' || raw.trim() === '') return null
  const path = logPath(raw, cwd)
  const cut = path.lastIndexOf('/')
  if (cut <= 0 || !/.\.md$/i.test(path.slice(cut + 1))) return null
  return sameFile(path.slice(0, cut), sessionsDir(cwd, dir)) ? { path, by } : null
}

/**
 * The binding after one log touch. Unbound, the touch binds. The same log keeps the
 * stronger touch. Another log displaces the binding only with a stronger touch (a Write
 * outranks an Edit, which outranks a Read), or with a Write once the bound log is closed
 * (a /task after a /close); so a Read of another log never displaces a Write. Returns
 * `current` itself when nothing changes.
 */
export function bindLog(current: LogBinding | null, touch: LogTouch, at: number, boundOpen = true): LogBinding | null {
  if (current === null) return { path: touch.path, by: touch.by, at }
  const stronger = LOG_RANK[touch.by] > LOG_RANK[current.by]
  if (sameFile(current.path, touch.path)) return stronger ? { ...current, by: touch.by, at } : current
  if (stronger || (touch.by === 'write' && !boundOpen)) return { path: touch.path, by: touch.by, at }
  return current
}

/** Whether bindLog's answer turns on the bound log being open: a Write of another log over a Write. */
export function needsOpenCheck(current: LogBinding | null, touch: LogTouch): boolean {
  return current !== null && current.by === 'write' && touch.by === 'write' && !sameFile(current.path, touch.path)
}

export function isOpenLog(text: string): boolean {
  return !text.includes('## Session Closed')
}

/** New asks from the side pass's texts; `source` 'build' for its multi-session list (0.6.0). */
export function freshAsks(
  texts: readonly string[],
  ids: readonly string[],
  at: number,
  source: 'ask' | 'build' = 'ask',
): Ask[] {
  return texts.map((text, i) => ({
    id: ids[i] ?? `a${at}-${i}`,
    text: cleanText(text),
    source,
    state: 'open',
    claimId: null,
    at,
  }))
}

/**
 * The asks a "done" answer may claim: open ones, and ticked goals still without a claim.
 * Never a build: a turn does not finish a multi-session build, and /close makes it a to-do.
 */
export function claimable(asks: readonly Ask[]): Ask[] {
  return asks.filter(
    a => a.source !== 'build' && (a.state === 'open' || (a.state === 'claimed' && a.claimId === null)),
  )
}

/**
 * Replaces the log's witness print, or appends one. The print ends with PRINT_END,
 * and only the text up to that marker is replaced, so notes written after a first
 * /wrap survive a second. A print without the marker (none should exist) is
 * replaced only up to the next heading.
 */
export function withPrint(text: string, section: string): string {
  const at = text.indexOf(PRINT_HEADING)
  if (at === -1) return `${text.replace(/\s*$/, '')}\n\n${section.trim()}\n`
  const marker = text.indexOf(PRINT_END, at)
  if (marker !== -1) {
    const tail = text.slice(marker + PRINT_END.length)
    return `${text.slice(0, at)}${section.trim()}${tail}`
  }
  const after = text.indexOf('\n## ', at + PRINT_HEADING.length)
  const tail = after === -1 ? '' : text.slice(after)
  return `${text.slice(0, at)}${section.trim()}\n${tail}`
}

/** The undone: open, or claimed but never witnessed. A build is not undone work for this session. */
export function undone(asks: readonly Ask[]): Ask[] {
  // Nor is an ask the close triage made a to-do (0.8.0): it lives on the board now.
  return asks.filter(
    a => a.source !== 'build' && a.settled === undefined && (a.state === 'open' || a.state === 'claimed'),
  )
}

/**
 * `/close` (Bradley, S162: "why on wrap and not on close as well?"): the close skill
 * reads the session log, so the companion writes its print there first, as /wrap does.
 */
export function isCloseCommand(text: string, commands: readonly string[] = DEFAULT_CLOSE_COMMANDS): boolean {
  return isConfiguredClose(text, commands)
}

/** The title every /tackle prompt opens with; its text is the companion's own list, never new asks. */
export const TACKLE_TITLE = 'Tackle the undone asks the witness holds for this session:'
/** The estate's first line: the title run as an /agile board (1.0: only where the estate is present). */
export const TACKLE_HEADER = `${ESTATE_TACKLE_SKILL} ${TACKLE_TITLE}`

/** The first line: the title, after the skill that runs it when one is named. */
export function tackleHeader(skill: string | null): string {
  return skill === null || skill === '' ? TACKLE_TITLE : `${skill} ${TACKLE_TITLE}`
}

/**
 * Whether a prompt is a /tackle run the companion wrote. Mining it re-recorded the
 * asks it lists as new ones (seen live S162: the three finished goals came back as
 * "Verify or finish ..." duplicates), so the side pass skips it.
 */
export function isTacklePrompt(text: string): boolean {
  return text.trim().replace(/^\/\S+\s+/, '').startsWith(TACKLE_TITLE)
}

/**
 * /tackle (Bradley, S162): the undone asks as an /agile run for this session to
 * direct. It goes into the prompt box for Bradley to read and send, never straight
 * to the model, and done still means witnessed. Null when nothing is undone.
 */
/**
 * The run opens with a sweep (Bradley, S163): much of what the witness holds is already
 * done and its evidence is often already in the context window, so dismissing on evidence
 * comes before slicing, and an agent is only for what survives it.
 */
export const SWEEP_FIRST =
  'First, before any agent: sweep. For every item, gather evidence from what is already in the context window and from the live stores, and dismiss straight off, with mcp__witness__confirm, every item that is already done; only what survives the sweep is sliced, and only it may get an agent.'

export function tacklePrompt(asks: readonly Ask[], skill: string | null = ESTATE_TACKLE_SKILL): string | null {
  const todo = undone(asks)
  if (todo.length === 0) return null
  const items = todo.map((a, i) => {
    const pale = a.state === 'claimed' ? ' (claimed done, never verified: verify it or finish it)' : ''
    return `${i + 1}. ${cleanText(a.text)}${pale}`
  })
  return [
    tackleHeader(skill),
    SWEEP_FIRST,
    ...items,
    'Done means witnessed: close each item with a read-back of what it changed (a test run, a fetch, a re-read). Leave anything only I can witness, such as a layout, for my look, and anything that needs my own hands (a login, a payment, a recording) for me: list it as mine, never give it to an agent.',
  ].join('\n')
}

const PASTED = /<pasted_content\b[^>]*>[\s\S]*?<\/pasted_content\b[^>]*>/g
const TACKLE_END = 'Done means witnessed'

/**
 * A prompt with what Bradley quoted cut out: a pasted block, and a /tackle prompt quoted
 * inside his own words (seen live, S166: pasting 405_85labs' /tackle to talk about it minted
 * five of 85labs' asks as his). A /tackle prompt sent whole is skipped before this.
 */
export function withoutQuoted(text: string): string {
  const unpasted = text.replace(PASTED, ' [pasted text] ')
  const title = unpasted.indexOf(TACKLE_TITLE)
  if (title === -1) return unpasted
  const skill = /\/\S+\s+$/.exec(unpasted.slice(0, title))
  const at = skill === null ? title : title - skill[0].length
  const end = unpasted.indexOf(TACKLE_END, at)
  const lineEnd = end === -1 ? -1 : unpasted.indexOf('\n', end)
  const tail = end === -1 || lineEnd === -1 ? '' : unpasted.slice(lineEnd)
  return `${unpasted.slice(0, at)} [a quoted /tackle prompt] ${tail}`
}

/**
 * The print, for a project that keeps no session log, on the /close prompt itself as a note
 * the close skill reads (a field report: 604_wasgenring's light protocol keeps none, so
 * Step 4b had nothing to triage).
 */
export function closePrintNote(print: string, estate = true): string {
  const settle = estate ? 'triage it in /close Step 4b' : 'settle it'
  return [
    `witness: this project keeps no session log, so the watch print could not be written into one. It follows here: ${settle} as if it stood in the log, and give the verdicts in the close summary.`,
    '',
    print.trim(),
  ].join('\n')
}

/** The first line of the prompt /wrap submits; its text is the companion's own print, never new asks. */
export const WRAP_READ_HEADER = 'witness /wrap: the watch is printed. Read it and settle what it lists.'

export function isWrapReadPrompt(text: string): boolean {
  return text.trim().startsWith(WRAP_READ_HEADER)
}

/**
 * What /wrap hands the main session (Bradley, 2026-10-08: "it would also be nice for the
 * main session to automatically read the printed work"): the print itself, and what to do
 * with each line. Submitted as a turn of its own; settling only, no new work.
 */
export function wrapReadPrompt(
  print: string,
  logPath: string | null,
  person: string = DEFAULT_PERSON,
  closeName = '/close',
): string {
  const who = personRef(person)
  const where =
    logPath === null
      ? 'It was not written to a session log (none is open for this session); the undone were kept for the next watch.'
      : `It is written into ${logPath}.`
  return [
    WRAP_READ_HEADER,
    where,
    `For every line not marked [x]: if it is done, read it back now and confirm it with ${CONFIRM_TOOL}; if ${who} called it off, drop it with ${CONFIRM_TOOL} and outcome "dropped", citing those words; otherwise leave it open and say in one line what it waits on. Builds stay for ${closeName} to make to-dos.`,
    'Start no new work. Then report in a few lines: what was confirmed, what was dropped, what stays open.',
    '',
    print.trim(),
  ].join('\n')
}

export function tally(asks: readonly Ask[], ledger: Ledger): string {
  const c = counts([...asks])
  const claims = ledger.claims.length
  const carried = c.carried > 0 ? `, ${c.carried} carried undone` : ''
  const builds = c.builds > 0 ? `, ${c.builds} build${c.builds === 1 ? '' : 's'} for the to-do list` : ''
  return `asks ${c.done}/${c.total} witnessed, ${c.pale} pale${carried}${builds}; claims ${claims - paleCount(ledger)}/${claims} witnessed`
}

files.hooks/ticket.ts:
// The estate ticket: the project tag, its board inbox, open Code to-dos and the push
// verdict, read from scripts/estate-status.py (1.0: an adapter, found or configured at
// session start; with no script there is no ticket, never `estate: ?`). Folded in from the estate-status mod
// (0.2.5) in 0.3.0 (Bradley, S165): two mods composing one band depended on which
// loaded first, and the engine gives no say over that, so the witness draws it alone.

import type { Ticket } from '../types'

export const TICKET_MS = 10 * 60_000
export const BAR_GLYPH = '\u258c'

export const UNAVAILABLE_TICKET: Ticket = { kind: 'unavailable' }

export type EstateStatus = {
  board_id?: string | null
  inbox_open?: number | null
  code_todos_open?: number | null
  metered?: string | null
}

/**
 * Project colours by board_id. Source: the Notion Global To-Do "Project" select
 * (Overseer red, Project Manager blue, Brand Manager yellow, The Stacks green,
 * Voice purple, HomeLab gray), ruled by Bradley 2026-10-06. Mid-tones that read on
 * light and dark terminals. Router is "default" there, so it carries no entry; any
 * other or null board_id gets no bar.
 */
export const BOARD_COLOURS: Readonly<Record<string, string>> = {
  overseer: '#D44C47',
  pm: '#447ACB',
  brand: '#CB912F',
  stacks: '#4C8F69',
  voice: '#9065B0',
  homelab: '#9B9A97',
}

/** The colour for a board, or null (no bar, default-colour tag). */
export function colourFor(board: string | null | undefined): string | null {
  if (board === null || board === undefined) return null
  return Object.prototype.hasOwnProperty.call(BOARD_COLOURS, board) ? (BOARD_COLOURS[board] ?? null) : null
}

const show = (v: string | number | null | undefined): string =>
  v === null || v === undefined ? '?' : String(v)

/** The ticket's parts, every count already display text. A null shows as `?`, never 0. */
export function ticketFromStatus(st: EstateStatus): Ticket {
  const inbox = typeof st.inbox_open === 'number' ? st.inbox_open : null
  return {
    kind: 'ok',
    colour: colourFor(st.board_id),
    tag: show(st.board_id),
    inbox: show(st.inbox_open),
    todos: show(st.code_todos_open),
    push: show(st.metered),
    warnInbox: inbox !== null && inbox > 0,
    warnPush: st.metered === 'METERED',
  }
}

/**
 * Parses the helper's stdout. Exit 2 means the database was unreachable but the JSON
 * is still printed (partial); no run, any other exit, or output that is not a JSON
 * object, is a failure and yields the unavailable ticket.
 */
export function ticketFromRun(run: { exitCode: number; stdout: string } | null): Ticket {
  if (run === null || (run.exitCode !== 0 && run.exitCode !== 2)) return UNAVAILABLE_TICKET
  try {
    const parsed: unknown = JSON.parse(run.stdout)
    if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) return UNAVAILABLE_TICKET
    return ticketFromStatus(parsed as EstateStatus)
  } catch {
    return UNAVAILABLE_TICKET
  }
}

files.hooks/usage.ts:
// What the witness's own Haiku side passes cost (S165). Bradley's worry: four witnesses
// in four sessions, each paying for a pass on every prompt. Each call's real usage, as
// the API reported it, is kept per session in its own file (four pods never write one
// file), and scripts/witness-usage.py sums a week of them. Recording spends no tokens.

import type { UsagePass, UsageRow } from '../types'

/** Under the user's home: `~/.claude/state/witness-usage`, where scripts/witness-usage.py reads. */
export const USAGE_SUBDIR = '.claude/state/witness-usage'

/** The usage folder for a home directory; null (no usage files) when the home is unknown. */
export function usageDir(home: string | undefined): string | null {
  const h = (home ?? '').trim().replace(/\\/g, '/').replace(/\/+$/, '')
  return h === '' ? null : `${h}/${USAGE_SUBDIR}`
}
export const USAGE_ROWS_CAP = 2_000

/** The parts of $.model.complete's result (ModelCompleteResult) this reads. */
type Answer =
  | {
      isAnswered: true
      text?: string
      usage: {
        input_tokens: number
        output_tokens: number
        cache_read_input_tokens: number
        cache_creation_input_tokens: number
      }
    }
  | { isAnswered: false; reason?: string; status?: number | null }

const count = (n: unknown): number => (typeof n === 'number' && Number.isFinite(n) ? n : 0)

/** One call: the counts the API reported, or zeros and not ok when it did not answer. */
export function usageRow(pass: UsagePass, at: number, r: Answer | null | undefined): UsageRow {
  if (r === null || r === undefined || !r.isAnswered) {
    return { at, pass, ok: false, in: 0, out: 0, cacheRead: 0, cacheWrite: 0 }
  }
  const u = r.usage
  return {
    at,
    pass,
    ok: true,
    in: count(u?.input_tokens),
    out: count(u?.output_tokens),
    cacheRead: count(u?.cache_read_input_tokens),
    cacheWrite: count(u?.cache_creation_input_tokens),
  }
}

/**
 * One model turn (0.5.0): the turn's own usage as turn.complete reported it, summed over
 * its requests, with the model that answered. Null when the turn reported none.
 */
export function turnRow(
  pass: UsagePass,
  at: number,
  usage:
    | {
        input_tokens: number
        output_tokens: number
        cache_read_input_tokens: number
        cache_creation_input_tokens: number
        model?: string
      }
    | null
    | undefined,
): UsageRow | null {
  if (usage === null || usage === undefined) return null
  return {
    at,
    pass,
    ok: true,
    in: count(usage.input_tokens),
    out: count(usage.output_tokens),
    cacheRead: count(usage.cache_read_input_tokens),
    cacheWrite: count(usage.cache_creation_input_tokens),
    model: typeof usage.model === 'string' ? usage.model : '?',
  }
}

/** Appends a row, keeping the newest USAGE_ROWS_CAP. */
export function addUsage(rows: readonly UsageRow[], row: UsageRow): UsageRow[] {
  return [...rows, row].slice(-USAGE_ROWS_CAP)
}

/** `<dir>/<YYYY-MM-DD the session started, UTC>/<session id>.json`; the id made path-safe. */
export function usagePath(dir: string, startedAt: number, sessionId: string): string {
  const day = new Date(startedAt).toISOString().slice(0, 10)
  return `${dir}/${day}/${sessionId.replace(/[^A-Za-z0-9._-]/g, '_')}.json`
}

export function usageFile(f: {
  sessionId: string
  repo: string
  startedAt: number
  model: string
  rows: readonly UsageRow[]
}): string {
  return JSON.stringify({ version: 1, ...f }, null, 1)
}

files.hooks/view.ts:
// The band's view model: everything the drawing needs, from plain state. Pure.

import type { Activity, Ask, Barnacle, Body, Costume, Hold, Ledger, Size, Speech } from '../types'
import { counts, nm } from './asks'
import { bellHalves, isIdle } from './bells'
import { colourFor, moodFor, sizeFor, speechBox } from './body'
import { barnacleCellsOf, bellCellsOf, eyeCellsOf, frame, propCells, withBarnacles, withBells, withMood, withProp } from './sprites'
import { paleCount, share } from './witness'

export const SAFELIGHT = '#C0392B'
/** Compact grew from 12 to 14 columns for the chime at the creature's back (1.1, Bradley 2026-10-09). */
export const SPRITE_WIDTH: Readonly<Record<Size, number>> = { full: 28, compact: 14 }
/** The row of the creature's eye per body and size; the speech tail sits on it. */
export const EYE_ROW: Readonly<Record<Body, Record<Size, number>>> = {
  phi: { full: 3, compact: 2 },
  phial: { full: 4, compact: 2 },
}
const MAX_SPEECH_WIDTH = 64
const MIN_SPEECH_WIDTH = 16

export type ViewInput = {
  body: Body
  frameIndex: number
  ledger: Ledger
  asks: Ask[]
  activity: Activity
  now: number
  speech: Speech | null
  hold: Hold | null
  barnacles: Barnacle[]
  working: boolean
  rowsLanded: boolean
  maxRows: number
  bodyColumns: number
  /** `left`: the creature sits at the right edge and faces its bubble. Default right (as drawn). */
  facing?: 'left' | 'right'
  /** What Phi wears (the /wear command, 1.1); `none` by default. A costume shows on the compact Phi only. */
  costume?: Costume
}

export type View = {
  size: Size
  sprite: string[]
  colour: string
  safelight: boolean
  /** Where the eyes are in `sprite` ([row, column], columns in code points), as drawn. */
  eyes: Array<[number, number]>
  /** The chime's four bell cells in `sprite`, top to bottom, as drawn; they take their own ink (1.1). */
  bells: Array<[number, number]>
  /** The cells the drawn barnacles occupy in `sprite`, as drawn; they take their own ink (1.1). */
  barnacles: Array<[number, number]>
  /** The cells the worn costume occupies in `sprite`, as drawn; red (1.1). Empty when Phi wears nothing. */
  costume: Array<[number, number]>
  status: string
  /** The speech as box-drawn rows (kept for the full-size print and tests). */
  speech: string[]
  /** The speech as plain data, for the band's bubble beside the creature. */
  bubble: { header: string; text: string } | null
}

/** Each glyph's mirror image; anything else is its own. */
const MIRROR: Readonly<Record<string, string>> = {
  '/': '\\',
  '\\': '/',
  '(': ')',
  ')': '(',
  '<': '>',
  '>': '<',
  // The horn tips are stored as 9 9 and read 6 6 on screen (Bradley, 2026-10-09); the lab's pair.
  '6': '9',
  '9': '6',
  // A half bell keeps its black half toward the shell when the creature turns (1.1).
  '◐': '◑',
  '◑': '◐',
  '[': ']',
  ']': '[',
  '{': '}',
  '}': '{',
  '`': "'",
  "'": '`',
}

/** The sprite facing the other way: each row reversed and its glyphs mirrored. Widths kept. */
export function mirror(rows: readonly string[]): string[] {
  return rows.map(row =>
    Array.from(row)
      .reverse()
      .map(c => MIRROR[c] ?? c)
      .join(''),
  )
}

export const HOLD_TEXT =
  'This write names nothing it touched. Add RETURNING (the CTE form), let it through once, or cancel.'

/** The speech that shows now: a hold always wins; an expired speech is gone. */
export function liveSpeech(speech: Speech | null, hold: Hold | null, now: number): Speech | null {
  if (hold !== null) return { header: 'HELD', text: HOLD_TEXT, full: true, until: null }
  if (speech === null) return null
  return speech.until !== null && speech.until <= now ? null : speech
}

/**
 * `asks 3/7 ~1 · witnessed 4/5 · HELD`, nothing absent shown as a zero. Trimmed to
 * what Bradley reads at a glance (S162): it rides on the ticket's one line.
 */
export function statusLine(ledger: Ledger, asks: Ask[], hold: Hold | null): string {
  const claims = ledger.claims.length
  const parts = [`asks ${nm(asks)}`]
  const c = counts(asks)
  if (c.carried > 0) parts.push(`carried ${c.carried}`)
  if (c.builds > 0) parts.push(`builds ${c.builds}`)
  if (claims > 0) parts.push(`witnessed ${claims - paleCount(ledger)}/${claims}`)
  if (hold !== null) parts.push('HELD')
  return parts.join(' · ')
}

function spriteRows(v: ViewInput, size: Size): string[] {
  const c = counts(v.asks)
  const mood = moodFor({
    held: v.hold !== null,
    working: v.working,
    idle: isIdle(v.activity, v.now),
    pale: paleCount(v.ledger),
    claims: v.ledger.claims.length,
    asksDone: c.done,
    asksTotal: c.total,
    rowsLanded: v.rowsLanded,
  })
  const base = frame(v.body, size, v.frameIndex)
  // Calm keeps each frame's own eye, so the idle frames can blink.
  const moody = mood === 'calm' ? base : withMood(base, v.body, size, mood)
  const belled = withBells(moody, v.body, size, bellHalves(v.activity))
  const crusted = withBarnacles(belled, v.body, size, v.barnacles.length)
  const costume = v.costume ?? 'none'
  return costume === 'none' ? crusted : withProp(crusted, v.body, size, costume)
}

export function buildView(v: ViewInput): View {
  const speech = liveSpeech(v.speech, v.hold, v.now)
  const size = sizeFor({
    moment: speech !== null && speech.full,
    maxRows: v.maxRows,
    bodyColumns: v.bodyColumns,
  })
  const sprite = spriteRows(v, size)
  const width = Math.min(MAX_SPEECH_WIDTH, v.bodyColumns - SPRITE_WIDTH[size] - 2)
  const box =
    speech !== null && width >= MIN_SPEECH_WIDTH
      ? speechBox({
          header: speech.header,
          text: speech.text,
          width,
          maxHeight: sprite.length - 1,
          tailRow: EYE_ROW[v.body][size] - 1,
        })
      : []
  const left = v.facing === 'left'
  // Cells as drawn: a creature turned to face left has every column counted from the far edge.
  const asDrawn = (cells: Array<[number, number]>): Array<[number, number]> =>
    cells.map(([r, c]): [number, number] => (left ? [r, Array.from(sprite[r] ?? '').length - 1 - c] : [r, c]))
  const eyes = asDrawn(eyeCellsOf(sprite, v.body, size))
  const bells = asDrawn(bellCellsOf(sprite, v.body, size))
  const barnacles = asDrawn(barnacleCellsOf(v.body, size, v.barnacles.length))
  const worn = v.costume ?? 'none'
  const costume =
    worn === 'none' || v.body !== 'phi' || size !== 'compact'
      ? []
      : asDrawn(propCells(worn).map(([r, c]): [number, number] => [r, c]))
  return {
    size,
    sprite: left ? mirror(sprite) : sprite,
    colour: colourFor(v.body, share(v.ledger)),
    safelight: v.hold !== null,
    eyes,
    bells,
    barnacles,
    costume,
    status: statusLine(v.ledger, v.asks, v.hold),
    speech: box,
    bubble: speech === null ? null : { header: speech.header, text: speech.text },
  }
}

files.hooks/notices.ts:
// The notice queue (Bradley, 2026-10-09): everything the bubble voices waits here, one
// shown at a time, `<n/m>` beside the Dismiss control when more than one waits. Order is
// the screen budget's (FAMILY.md section 4); nothing is dropped. Pure: time and ids are
// arguments.

import type { Notice, NoticeKind, NoticeQueue } from '../types'

/** Screen-budget order: a held write, a note from beneath, the witness's own speech, a guest. */
export const PRIORITY: Readonly<Record<NoticeKind, number>> = { held: 0, beneath: 1, own: 2, guest: 3 }

/** The key bound while a dismissable witness notice shows; the Button draws `0: Dismiss`. */
export const DISMISS_KEY = '0'
export const DISMISS_LABEL = 'Dismiss'

export const EMPTY_QUEUE: NoticeQueue = { items: [], seen: 0 }

export type NoticeInput = Omit<Notice, 'id' | 'at'>

function expired(n: Notice, now: number): boolean {
  return n.until !== null && n.until <= now
}

/** Stable by priority, then arrival. */
function ordered(items: readonly Notice[]): Notice[] {
  return items
    .map((n, i) => ({ n, i }))
    .sort((a, b) => PRIORITY[a.n.kind] - PRIORITY[b.n.kind] || a.n.at - b.n.at || a.i - b.i)
    .map(x => x.n)
}

/**
 * Adds a notice. One whose text is already waiting is not added twice: the waiting one
 * takes the newer header and expiry, keeping its place.
 */
export function enqueue(q: NoticeQueue, input: NoticeInput, id: string, at: number): NoticeQueue {
  const same = q.items.find(n => n.text === input.text && !expired(n, at))
  if (same !== undefined) {
    const items = q.items.map(n => (n === same ? { ...n, header: input.header, full: input.full, until: input.until } : n))
    return { ...q, items }
  }
  const fresh = q.items.filter(n => !(n.text === input.text && expired(n, at)))
  return { ...q, items: ordered([...fresh, { ...input, id, at }]) }
}

/** Drops what has expired, counting it as seen; an emptied queue starts its count again. */
export function settle(q: NoticeQueue, now: number): NoticeQueue {
  const live = q.items.filter(n => !expired(n, now))
  if (live.length === 0) return EMPTY_QUEUE
  const gone = q.items.length - live.length
  return gone === 0 ? q : { items: live, seen: q.seen + gone }
}

/** Removes one notice by id, as an answered held write is; it counts as seen. */
export function remove(q: NoticeQueue, id: string): NoticeQueue {
  const items = q.items.filter(n => n.id !== id)
  if (items.length === q.items.length) return q
  return items.length === 0 ? EMPTY_QUEUE : { items, seen: q.seen + 1 }
}

/** Only the witness's own notices: a held write is answered, a note from beneath is the engine's. */
export function dismissable(n: Notice | null): boolean {
  return n !== null && (n.kind === 'own' || n.kind === 'guest')
}

export type Showing = {
  /** The notice in the bubble; null when a note from beneath (the engine's) or nothing shows. */
  notice: Notice | null
  /** True when the note from beneath holds the bubble. */
  beneath: boolean
  /** Position of the one showing, 1-based; 0 when nothing shows. */
  n: number
  /** Everything waiting, the one showing included. */
  m: number
}

/**
 * What the bubble shows now. A note from beneath is the engine's, drawn by it and
 * dismissed with its own controls: it is counted, never queued.
 */
export function showing(q: NoticeQueue, beneath: boolean, now: number): Showing {
  const live = q.items.filter(n => !expired(n, now))
  const gone = q.items.length - live.length
  const held = live.filter(n => n.kind === 'held')
  const rest = live.filter(n => n.kind !== 'held')
  const waiting = live.length + (beneath ? 1 : 0)
  if (waiting === 0) return { notice: null, beneath: false, n: 0, m: 0 }
  const seen = q.seen + gone
  const head = held[0] ?? (beneath ? null : (rest[0] ?? null))
  return { notice: head, beneath: head === null, n: seen + 1, m: seen + waiting }
}

/** Dismisses the witness notice showing; a held write or a note from beneath is left as it is. */
export function dismiss(q: NoticeQueue, beneath: boolean, now: number): NoticeQueue {
  const settled = settle(q, now)
  const shown = showing(settled, beneath, now).notice
  return shown !== null && dismissable(shown) ? remove(settled, shown.id) : settled
}

/** `<n/m>` when more than one waits; '' for a single notice. */
export function countText(n: number, m: number): string {
  return m > 1 && n > 0 ? `<${n}/${m}>` : ''
}

/** The footer as drawn: `0: Dismiss <n/m>`, either part absent when it does not apply. */
export function footerText(canDismiss: boolean, n: number, m: number): string {
  const dismissPart = canDismiss ? `${DISMISS_KEY}: ${DISMISS_LABEL}` : ''
  return [dismissPart, countText(n, m)].filter(p => p !== '').join(' ')
}

/** Greedy word wrap at `width` (a word longer than the line is split); never empty. */
export function wrapLines(text: string, width: number): string[] {
  const w = Math.max(1, width)
  const lines: string[] = []
  let line = ''
  for (const raw of text.split(/\s+/).filter(x => x.length > 0)) {
    let word = raw
    while (word.length > w) {
      if (line !== '') lines.push(line)
      line = ''
      lines.push(word.slice(0, w))
      word = word.slice(w)
    }
    if (line !== '' && line.length + 1 + word.length > w) {
      lines.push(line)
      line = word
    } else {
      line = line === '' ? word : `${line} ${word}`
    }
  }
  if (line !== '') lines.push(line)
  return lines.length > 0 ? lines : ['']
}

/**
 * Where the footer goes without making the bubble taller: on the text's last row when it
 * fits there, otherwise on the header row.
 */
export function footerRow(lines: readonly string[], inner: number, footer: string): 'last' | 'header' {
  if (footer === '') return 'last'
  const last = lines[lines.length - 1] ?? ''
  return last.length + 1 + footer.length <= inner ? 'last' : 'header'
}

